int merge(const vector<int> &a, const vector<int> &b) {
    int n = sz(a);
    int res = 0;
    for (int c = 0, i = 0, j = 0; c < n; ++c) {
        if (a[i] > b[j]) {
            ++res;
            ++i;
        } else if (a[i] < b[j]) {
            ++j;
        } else {
            assert(0);
        }
    }
    return res;
}

void solve() {
