    vector<int> pref_min(n), suf_max(n);
    pref_min[0] = 0;
    for (int i = 1; i < n; ++i) {
        pref_min[i] = pref_min[i - 1];
        if (a[i] < a[pref_min[i - 1]]) {
            pref_min[i] = i;
        }
    }
    suf_max[n - 1] = n - 1;
    for (int i = n - 2; i >= 0; --i) {
        suf_max[i] = suf_max[i + 1];
