    vi path;
    auto dfs = [&] (auto &&self, int v, int p, int t) -> bool {
        path.push_back(v);
        if (v == t) return true;
        for(auto &u : g[v]) {
            if (u == p) continue;
            if (self(self, u, v, t)) return true;
