        for(auto &v : q) {
            if (ok[v] || cur[v] || was[v] == t) continue;
            was[v] = t;
            bool nei = 0;
            for(auto &u : g[v]) nei |= ok[u];
            if (t && !nei) continue;
            nxt.push_back(v);
        }

