#include "bits/stdc++.h"

using namespace std;

void solve() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    vector<int> b(n);
    for (int i = 0; i < n; i++) {
        cin >> b[i];
    }
    vector<int> want(n);
    auto make = [&] (int i, int x, int y) {
        if (!want[i]) {
            if (a[i] != x) {
                swap(a[i], b[i]);
            }
            want[i] = 1;
        }
    };
    const int N = 2 * n + 22;
    vector<vector<pair<int, int>>> g(N);
    for (int i = 0; i < n; i++) {
        g[a[i]].push_back({b[i], i});
        g[b[i]].push_back({a[i], i});
    }
    vector<int> used(N);
    auto dfs = [&] (auto&& dfs, int v, int h) -> void {
        used[v] = h;
        for (auto& [u, i] : g[v]) {
            if (used[u] <= 0) {
                make(i, v, u);
                dfs(dfs, u, h + 1);
            } else if (used[u] < used[v]) {
                make(i, v, u);
            }
        }
    };
    for (int i = 0; i < N; i++) {
        if (used[i] == 0 && int(g[i].size()) == 1) {
            dfs(dfs, i, 1);
        }
    }
    int rt;
    auto find = [&] (auto&& find, int v, int pr) -> void {
        used[v] = -1;
        for (auto& [u, i] : g[v]) {
            if (used[u] == 0) {
                find(find, u, i);
            } else if (i != pr) {
                rt = u;
            }
        }
    };
    for (int i = 0; i < N; i++) {
        if (used[i] == 0 && !g[i].empty()) {
            rt = -1;
            find(find, i, -1);
            dfs(dfs, rt, 1);
        }
    }
    cout << set<int>(a.begin(), a.end()).size() + set<int>(b.begin(), b.end()).size() << '\n';
    for (int i = 0; i < n; i++) {
        cout << a[i] << " ";
    }
    cout << '\n';
    for (int i = 0; i < n; i++) {
        cout << b[i] << " ";
    }
    cout << '\n';
}

int main() {
    ios_base::sync_with_stdio(0);
